            )
        } else {
            BannerEntry::new(
                "💸",
                "Ignored Extensions",
                &format!("[{}]", config.dont_collect.join(", ")),
            )
        };

        let offset = std::cmp::min(config.data.len(), 30);
        let data = String::from_utf8(config.data[..offset].to_vec())
