                "temp_request_file_{}.txt",
                SystemTime::now()
                    .duration_since(UNIX_EPOCH)
                    .unwrap()
                    .as_nanos()
            ));

            let config: Configuration = Configuration {
                request_file: temp_dir.to_str().unwrap().to_string(),
                ..Default::default()
            };

            let file = File::create(&temp_dir).unwrap();

            Self {
                path: temp_dir,
                config,
                file,
            }
        }

